  virtual std::shared_future<std::any>
  fetchOrdersByStatus(std::any status, std::any symbol = std::any{},
                      std::any since = std::any{}, std::any limit = std::any{},
                      std::any params = ccxt::dict{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = std::any{};
                        std::any request = ccxt::dict{
                            {std::string("state"), status},
                        };
                        if (isTrue(!isEqual(symbol, std::any{}))) {
                          market = this->market(symbol);
                          ::setValue(request, std::string("market_symbol"),
                                     ::getValue(market, std::string("id")));
                        }
                        if (isTrue(!isEqual(since, std::any{}))) {
                          ::setValue(request, std::string("start_time"),
                                     this->iso8601(since));
                        }
                        if (isTrue(!isEqual(limit, std::any{}))) {
                          ::setValue(request, std::string("page_size"), limit);
                          if (isTrue(isGreaterThan(limit, 100))) {
                            ::setValue(request, std::string("page_size"), 100);
                          }
                        }
                        std::any response = awaitValue(this->v3PrivateGetOrders(
                            this->extend(request, params)));
                        std::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseOrders(data);
                      })
        .share();
  }

  /**
   * @method
   * @name foxbit#createOrder
   * @description Create an order with the specified characteristics
   * @see
   * https://docs.foxbit.com.br/rest/v3/#tag/Trading/operation/OrdersController_create
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market', 'limit', 'stop_market', 'stop_limit',
   * 'instant'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much you want to trade in units of the base
   * currency
   * @param {float} [price] the price at which the order is to be fullfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.timeInForce] "GTC", "FOK", "IOC", "PO"
   * @param {float} [params.triggerPrice] The time in force for the order. One
   * of GTC, FOK, IOC, PO. See .features or foxbit's doc to see more details.
   * @param {bool} [params.postOnly] true or false whether the order is
   * post-only
   * @param {string} [params.clientOrderId] a unique identifier for the order
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 type = toUpperCase(type);
                 if (isTrue(
                         isTrue(
                             isTrue(isTrue(isTrue(!isEqual(
                                               type, std::string("LIMIT"))) &&
                                           isTrue(!isEqual(
                                               type, std::string("MARKET")))) &&
                                    isTrue(!isEqual(
                                        type, std::string("STOP_MARKET")))) &&
                             isTrue(
                                 !isEqual(type, std::string("STOP_LIMIT")))) &&
                         isTrue(!isEqual(type, std::string("INSTANT"))))) {
                   throw InvalidOrder(toString(
                       add(add(std::string("Invalid order type: "), type),
                           std::string(". Must be one of: limit, market, "
                                       "stop_market, stop_limit, instant."))));
                 }
                 std::any timeInForce =
                     this->safeStringUpper(params, std::string("timeInForce"));
                 std::any postOnly =
                     this->safeBool(params, std::string("postOnly"), false);
                 std::any triggerPrice =
                     this->safeNumber(params, std::string("triggerPrice"));
                 if (isTrue(isEqual(side, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " createOrder() requires a side argument"))));
                 }
                 std::any request = ccxt::dict{
                     {std::string("market_symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("side"), toUpperCase(side)},
                     {std::string("type"), type},
                 };
                 if (isTrue(isTrue(isEqual(type, std::string("STOP_MARKET"))) ||
                            isTrue(isEqual(type, std::string("STOP_LIMIT"))))) {
                   if (isTrue(isEqual(triggerPrice, std::any{}))) {
                     throw InvalidOrder(toString(
                         add(add(std::string("Invalid order type: "), type),
                             std::string(". Must have triggerPrice."))));
                   }
                 }
                 if (isTrue(!isEqual(timeInForce, std::any{}))) {
                   if (isTrue(isEqual(timeInForce, std::string("PO")))) {
                     ::setValue(request, std::string("post_only"), true);
                   } else {
                     ::setValue(request, std::string("time_in_force"),
                                timeInForce);
                   }
                 }
                 if (isTrue(isEqual(postOnly, true))) {
                   ::setValue(request, std::string("post_only"), true);
                 }
                 if (isTrue(!isEqual(triggerPrice, std::any{}))) {
                   ::setValue(request, std::string("stop_price"),
                              this->priceToPrecision(symbol, triggerPrice));
                 }
                 if (isTrue(isEqual(type, std::string("INSTANT")))) {
                   ::setValue(request, std::string("amount"),
                              this->priceToPrecision(symbol, amount));
                 } else {
                   ::setValue(request, std::string("quantity"),
                              this->amountToPrecision(symbol, amount));
                 }
                 if (isTrue(isTrue(isEqual(type, std::string("LIMIT"))) ||
                            isTrue(isEqual(type, std::string("STOP_LIMIT"))))) {
                   ::setValue(request, std::string("price"),
                              this->priceToPrecision(symbol, price));
                 }
                 std::any clientOrderId =
                     this->safeString(params, std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                   ::setValue(request, std::string("client_order_id"),
                              clientOrderId);
                 }
                 params = this->omit(params,
                                     ccxt::list{std::string("timeInForce"),
                                                std::string("postOnly"),
                                                std::string("triggerPrice"),
                                                std::string("clientOrderId")});
                 std::any response = awaitValue(
                     this->v3PrivatePostOrders(this->extend(request, params)));
                 // {
                 //     "id": 1234567890,
                 //     "sn": "OKMAKSDHRVVREK",
                 //     "client_order_id": "451637946501"
                 // }
                 return this->parseOrder(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name foxbit#createOrders
   * @description create a list of trade orders
   * @see https://docs.foxbit.com.br/rest/v3/#tag/Trading/operation/createBatch
   * @param {Array} orders list of orders to create, each object should contain
   * the parameters required by createOrder, namely symbol, type, side, amount,
   * price and params
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrders(std::any orders, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any ordersRequests = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   std::any order = this->safeDict(orders, i);
                   std::any symbol =
                       this->safeString(order, std::string("symbol"));
                   std::any market = this->market(symbol);
                   std::any type =
                       this->safeStringUpper(order, std::string("type"));
                   std::any orderParams = this->safeDict(
                       order, std::string("params"), ccxt::dict{});
                   if (isTrue(
                           isTrue(
                               isTrue(
                                   isTrue(isTrue(!isEqual(
                                              type, std::string("LIMIT"))) &&
                                          isTrue(!isEqual(
                                              type, std::string("MARKET")))) &&
                                   isTrue(!isEqual(
                                       type, std::string("STOP_MARKET")))) &&
                               isTrue(!isEqual(type,
                                               std::string("STOP_LIMIT")))) &&
                           isTrue(!isEqual(type, std::string("INSTANT"))))) {
                     throw InvalidOrder(toString(add(
                         add(std::string("Invalid order type: "), type),
                         std::string(". Must be one of: limit, market, "
                                     "stop_market, stop_limit, instant."))));
                   }
                   std::any timeInForce = this->safeStringUpper(
                       orderParams, std::string("timeInForce"));
                   std::any postOnly = this->safeBool(
                       orderParams, std::string("postOnly"), false);
                   std::any triggerPrice = this->safeNumber(
                       orderParams, std::string("triggerPrice"));
                   std::any request = ccxt::dict{
                       {std::string("market_symbol"),
                        ::getValue(market, std::string("id"))},
                       {std::string("side"),
                        this->safeStringUpper(order, std::string("side"))},
                       {std::string("type"), type},
                   };
                   if (isTrue(
                           isTrue(isEqual(type, std::string("STOP_MARKET"))) ||
                           isTrue(isEqual(type, std::string("STOP_LIMIT"))))) {
                     if (isTrue(isEqual(triggerPrice, std::any{}))) {
                       throw InvalidOrder(toString(
                           add(add(std::string("Invalid order type: "), type),
                               std::string(". Must have triggerPrice."))));
                     }
                   }
                   if (isTrue(!isEqual(timeInForce, std::any{}))) {
                     if (isTrue(isEqual(timeInForce, std::string("PO")))) {
                       ::setValue(request, std::string("post_only"), true);
                     } else {
                       ::setValue(request, std::string("time_in_force"),
                                  timeInForce);
                     }
                     deleteKey(orderParams, std::string("timeInForce"));
                   }
                   if (isTrue(isEqual(postOnly, true))) {
                     ::setValue(request, std::string("post_only"), true);
                     deleteKey(orderParams, std::string("postOnly"));
                   }
                   if (isTrue(!isEqual(triggerPrice, std::any{}))) {
                     ::setValue(request, std::string("stop_price"),
                                this->priceToPrecision(symbol, triggerPrice));
                     deleteKey(orderParams, std::string("triggerPrice"));
                   }
                   if (isTrue(isEqual(type, std::string("INSTANT")))) {
                     ::setValue(request, std::string("amount"),
                                this->priceToPrecision(
                                    symbol, this->safeString(
                                                order, std::string("amount"))));
                   } else {
                     ::setValue(request, std::string("quantity"),
                                this->amountToPrecision(
                                    symbol, this->safeString(
                                                order, std::string("amount"))));
                   }
                   if (isTrue(
                           isTrue(isEqual(type, std::string("LIMIT"))) ||
                           isTrue(isEqual(type, std::string("STOP_LIMIT"))))) {
                     ::setValue(request, std::string("price"),
                                this->priceToPrecision(
                                    symbol, this->safeString(
                                                order, std::string("price"))));
                   }
                   arrayPush(ordersRequests,
                             this->extend(request, orderParams));
                 }
                 std::any createOrdersRequest = ccxt::dict{
                     {std::string("data"), ordersRequests},
                 };
                 std::any response = awaitValue(this->v3PrivatePostOrdersBatch(
                     this->extend(createOrdersRequest, params)));
                 // {
                 //     "data": [
                 //         {
                 //         "side": "BUY",
                 //         "type": "LIMIT",
                 //         "market_symbol": "btcbrl",
                 //         "client_order_id": "451637946501",
                 //         "remark": "A remarkable note for the order.",
                 //         "quantity": "0.42",
                 //         "price": "250000.0",
                 //         "post_only": true,
                 //         "time_in_force": "GTC"
                 //         }
                 //     ]
                 // }
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseOrders(data);
               })
        .share();
  }

  /**
   * @method
   * @name foxbit#cancelOrder
   * @description Cancel open orders.
   * @see
   * https://docs.foxbit.com.br/rest/v3/#tag/Trading/operation/OrdersController_cancel
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelOrder(std::any id, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any request = ccxt::dict{
                            {std::string("id"), this->parseNumber(id)},
                            {std::string("type"), std::string("ID")},
                        };
                        std::any response =
                            awaitValue(this->v3PrivatePutOrdersCancel(
                                this->extend(request, params)));
                        // {
                        //     "data": [
                        //         {
                        //         "sn": "OKMAKSDHRVVREK",
                        //         "id": 123456789
                        //         }
                        //     ]
                        // }
                        std::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        std::any result = this->safeDict(data, 0, ccxt::dict{});
                        return this->parseOrder(result);
                      })
        .share();
  }

  /**
   * @method
   * @name foxbit#cancelAllOrders
   * @description Cancel all open orders or all open orders for a specific
   * market.
   * @see
   * https://docs.foxbit.com.br/rest/v3/#tag/Trading/operation/OrdersController_cancel
   * @param {string} [symbol] unified market symbol of the market to cancel
   * orders in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelAllOrders(std::any symbol = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any request = ccxt::dict{
                            {std::string("type"), std::string("ALL")},
                        };
                        if (isTrue(!isEqual(symbol, std::any{}))) {
                          std::any market = this->market(symbol);
                          ::setValue(request, std::string("type"),
                                     std::string("MARKET"));
                          ::setValue(request, std::string("market_symbol"),
                                     ::getValue(market, std::string("id")));
                        }
                        std::any response =
                            awaitValue(this->v3PrivatePutOrdersCancel(
                                this->extend(request, params)));
                        // {
                        //     "data": [
                        //         {
                        //           "sn": "OKMAKSDHRVVREK",
                        //           "id": 123456789
                        //         }
                        //     ]
                        // }
                        return ccxt::list{this->safeOrder(ccxt::dict{
                            {std::string("info"), response},
                        })};
                      })
        .share();
  }

