                 //             "amount": "1.0",
                 //             "fee": "0.1",
                 //             "created_at": "2022-02-18T22:06:32.999Z",
                 //             "details_crypto": {
                 //                 "transaction_id":
                 //                 "e20f035387020c5d5ea18ad53244f09f3",
                 //                 "destination_address":
                 //                 "2N2rTrnKEFcyJjEJqvVjgWZ3bKvKT7Aij61"
                 //             },
